def ways_to_split_array(nums):
    n = len(nums)
    count = 0
    for i in range(n - 1):
        left_sum = sum(nums[:i + 1])                              # resums the left side from scratch every time
        right_sum = sum(nums[i + 1:])                                # resums the right side from scratch every time
        if left_sum >= right_sum:
            count += 1
    return count


if __name__ == "__main__":
    print(ways_to_split_array([10, 4, -8, 7]))

