import java.util.*;

public class Main {
    int waysToSplitArray(int[] nums) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n - 1; i++) {
            int leftSum = 0;
            for (int j = 0; j <= i; j++) leftSum += nums[j];                // resums the left side from scratch every time
            int rightSum = 0;
            for (int j = i + 1; j < n; j++) rightSum += nums[j];              // resums the right side from scratch every time
            if (leftSum >= rightSum) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.waysToSplitArray(new int[]{10, 4, -8, 7}));
    }
}

